package com.footballacademy.services.scouting;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class ScoutingService { private final ScoutingReportRepository reports; private final PlayerRepository players; private final ScouterRepository scouters; private final MatchRepository matches; public ScoutingService(ScoutingReportRepository reports, PlayerRepository players, ScouterRepository scouters, MatchRepository matches){this.reports=reports;this.players=players;this.scouters=scouters;this.matches=matches;} @Transactional public ScoutingReport createReport(Long playerId, Long scouterId, Long matchId){Player p=players.findById(playerId).orElseThrow(); Scouter s=scouters.findById(scouterId).orElseThrow(); ScoutingReport r=new ScoutingReport(); r.setPlayer(p); r.setScouter(s); r.setAcademy(p.getAcademy()!=null?p.getAcademy():s.getAcademy()); if(matchId!=null)matches.findById(matchId).ifPresent(r::setMatch); return reports.save(r);} @Transactional public ScoutingReport updateReport(Long reportId, ScoutingReport patch){ScoutingReport r=reports.findById(reportId).orElseThrow(); r.setTechnicalScore(patch.getTechnicalScore()); r.setTacticalScore(patch.getTacticalScore()); r.setPhysicalScore(patch.getPhysicalScore()); r.setMentalScore(patch.getMentalScore()); r.setPotentialScore(patch.getPotentialScore()); r.setStyleFitScore(patch.getStyleFitScore()); r.setRecommendation(patch.getRecommendation()); r.setNotes(patch.getNotes()); r.setStatus(patch.getStatus()); return reports.save(r);} @Transactional public void approveReport(Long reportId){ScoutingReport r=reports.findById(reportId).orElseThrow(); r.approve(); reports.save(r);} @Transactional public void rejectReport(Long reportId){ScoutingReport r=reports.findById(reportId).orElseThrow(); r.reject(); reports.save(r);} public List<Player> getShortlist(Long academyId, Long divisionId){return reports.findByAcademy_IdAndStatus(academyId, ScoutingStatus.SHORTLISTED).stream().map(ScoutingReport::getPlayer).filter(p->p!=null&&(divisionId==null||(p.getDivision()!=null&&divisionId.equals(p.getDivision().getId())))).distinct().toList();} }
